-- 2025 grant candidates from "Congressional App Challenge 2025 grants.xlsx"
-- (sheet "2025 Grant Candidates", rows 2-174): 173 records, $12,740,447 total.
--
-- Run in the Supabase SQL Editor after supabase_grants_setup.sql, then run
-- data_fixes_2025.sql.
-- Safe to re-run: rows from this file are upserted by source row, and any
-- row that matches a grant already loaded from a different file is skipped.
--
-- Pre-load checks on the workbook (2026-10-24):
--   * 0 exact duplicate rows and 0 duplicates on filing ID + funder EIN +
--     recipient + recipient EIN + amount + city + ZIP + purpose.
--   * 0 overlaps with the 400 tax-year-2024 rows already loaded (no shared
--     filing IDs; no filing + recipient + amount matches).
--   * All EINs 9 digits, ZIPs 5 or 9 digits, amounts whole dollars, URLs https.

begin;

-- Schema prep -----------------------------------------------------------
-- 990-PF rows often have no recipient EIN, and this workbook has no
-- match-evidence column, so both become optional. The existing format
-- check on recipient_ein still applies whenever a value is present.
alter table public.source_matched_grants
    alter column recipient_ein drop not null,
    alter column match_evidence drop not null;

-- Grant purpose is new in this workbook.
alter table public.source_matched_grants
    add column if not exists purpose text;

-- The app reads purpose through grants_public, which data_fixes_2025.sql
-- defines; views are not changed here so this script stays re-runnable.

-- Data ------------------------------------------------------------------
insert into public.source_matched_grants (
    source_file, source_sheet, source_row_number, funder, funder_ein,
    recipient, recipient_ein, amount_usd, tax_year, city, state, zip,
    street_address, filing_id, filing_url, source, match_evidence,
    county_confirmation, verification_status, purpose
)
