    source_file, source_sheet, source_row_number, funder, funder_ein,
    recipient, recipient_ein, amount_usd, tax_year, city, state, zip,
    street_address, filing_id, filing_url, source, match_evidence,
    county_confirmation, verification_status, purpose
)
-- Skip a row if the same grant was already loaded from another file.
where not exists (
    select 1
    from public.source_matched_grants g
    where g.source_file <> v.source_file
      and g.filing_id = v.filing_id
      and g.funder_ein = v.funder_ein
      and upper(trim(g.recipient)) = upper(trim(v.recipient))
      and g.amount_usd = v.amount_usd
      and g.tax_year = v.tax_year
      and coalesce(upper(trim(g.purpose)), '') = coalesce(upper(trim(v.purpose)), '')
)
on conflict (source_file, source_sheet, source_row_number) do update set
    funder = excluded.funder,
    funder_ein = excluded.funder_ein,
    recipient = excluded.recipient,
    recipient_ein = excluded.recipient_ein,
    amount_usd = excluded.amount_usd,
    tax_year = excluded.tax_year,
    city = excluded.city,
    state = excluded.state,
    zip = excluded.zip,
    street_address = excluded.street_address,
    filing_id = excluded.filing_id,
    filing_url = excluded.filing_url,
    source = excluded.source,
    match_evidence = excluded.match_evidence,
    county_confirmation = excluded.county_confirmation,
    verification_status = excluded.verification_status,
    purpose = excluded.purpose,
    loaded_at = now();

commit;

